    public enum SpatialMigrationJournalStage { DescriptorPinned=1, BackupVerified=2, CandidateVerified=3, Replaced=4, DurableVerified=5, Finalized=6, OriginalRestored=7 }
    public sealed class SpatialMigrationJournal
